#!/usr/bin/env python3
"""Procedural, tileable 32x32 ground textures for the kingdom (original art, generated by this script).
Drawn at 2x nearest in game (64 px tiles). Palette follows the Airron's Fall ash/moss/ember look.
Run: python3 tools/art/kingdom_tiles.py  ->  assets/kingdom/tiles/*.png
"""
import math, os, random
import numpy as np
from PIL import Image

N = 32
OUT = "assets/kingdom/tiles"


def tnoise(seed, octaves=((2, 1.0), (4, 0.5), (8, 0.25))):
    """Tileable noise: sum of integer-frequency sines with random phases (wraps exactly at N)."""
    rng = np.random.default_rng(seed)
    y, x = np.mgrid[0:N, 0:N] / N * 2 * math.pi
    v = np.zeros((N, N))
    for f, a in octaves:
        for _ in range(3):
            fx, fy = rng.integers(-f, f + 1, 2)
            if fx == 0 and fy == 0:
                fx = f
            v += a * np.sin(fx * x + fy * y + rng.uniform(0, 6.3))
    v -= v.min(); v /= v.max()
    return v


def ramp(v, cols):
    cols = np.array(cols, np.float32)
    idx = np.clip((v * len(cols)).astype(int), 0, len(cols) - 1)
    return cols[idx]


def save(name, rgb):
    Image.fromarray(np.clip(rgb, 0, 255).astype(np.uint8), "RGB").save(os.path.join(OUT, name + ".png"))


def blades(img, seed, cols, count=34):
    rnd = random.Random(seed)
    for _ in range(count):
        x, y = rnd.randrange(N), rnd.randrange(N)
        h = rnd.choice((2, 3, 3, 4))
        c = rnd.choice(cols)
        for k in range(h):
            img[(y - k) % N, (x + (1 if k == h - 1 and rnd.random() < 0.4 else 0)) % N] = c
        img[(y + 1) % N, x % N] = np.array(cols[0]) * 0.75


def grass(name, seed, cols, blade_cols):
    img = ramp(tnoise(seed), cols)
    blades(img, seed + 1, blade_cols)
    save(name, img)


def stones(name, seed, base, mortar, rows=4, jitter=0.12, light=1.12):
    rnd = random.Random(seed)
    img = np.zeros((N, N, 3), np.float32) + mortar
    n = tnoise(seed, ((4, 1.0), (8, 0.5)))
    h = N // rows
    for r in range(rows):
        off = (h if r % 2 else 0)
        x = off
        while x < N + off:
            w = rnd.choice((h, h, h + 4, h - 2))
            c = np.array(base) * (1 + rnd.uniform(-jitter, jitter))
            for yy in range(r * h + 1, r * h + h):
                for xx in range(x + 1, x + w):
                    shade = light if yy == r * h + 1 else (0.82 if yy == r * h + h - 1 else 1.0)
                    img[yy % N, xx % N] = c * shade * (0.92 + 0.16 * n[yy % N, xx % N])
            x += w
    save(name, img)


def main():
    os.makedirs(OUT, exist_ok=True)
    grass("grass", 1, [(58, 74, 46), (66, 84, 50), (74, 94, 54), (84, 104, 58)], [(96, 120, 62), (110, 132, 66), (70, 90, 50)])
    grass("forest_floor", 2, [(38, 50, 34), (44, 58, 38), (50, 64, 40), (60, 66, 42)], [(70, 88, 50), (92, 72, 44), (54, 70, 42)])
    grass("highland", 3, [(86, 84, 60), (96, 92, 64), (106, 100, 70), (116, 108, 76)], [(128, 120, 80), (90, 96, 62), (140, 128, 86)])
    # sand with ripples and shell flecks
    n = tnoise(4, ((2, 1.0), (6, 0.4)))
    y = np.mgrid[0:N, 0:N][0]
    rip = (np.sin((y + n * 6) / N * 2 * math.pi * 4) * 0.5 + 0.5) * 0.35
    save("sand", ramp(np.clip(n * 0.7 + rip, 0, 1), [(150, 128, 92), (164, 142, 102), (178, 156, 112), (190, 170, 124)]))
    # dirt road with pebbles
    img = ramp(tnoise(5, ((2, 1.0), (8, 0.6))), [(92, 70, 48), (104, 80, 54), (116, 90, 60), (126, 100, 68)])
    rnd = random.Random(6)
    for _ in range(14):
        x, yy = rnd.randrange(N), rnd.randrange(N)
        img[yy, x] = (150, 136, 112); img[(yy + 1) % N, x] = (70, 56, 40)
    save("road", img)
    stones("cobble", 7, (118, 108, 96), (56, 48, 42), rows=4)
    stones("flagstone", 8, (100, 92, 84), (48, 42, 38), rows=2, jitter=0.08)
    stones("wall", 9, (74, 64, 56), (34, 28, 24), rows=4, jitter=0.1, light=1.18)
    # cliff rock: vertical strata
    n = tnoise(10, ((2, 1.0), (4, 0.6), (8, 0.3)))
    x = np.mgrid[0:N, 0:N][1]
    strata = (np.sin((x + n * 8) / N * 2 * math.pi * 3) * 0.5 + 0.5)
    save("cliff", ramp(np.clip(n * 0.5 + strata * 0.5, 0, 1), [(52, 44, 40), (66, 56, 50), (82, 70, 62), (98, 86, 76)]))
    # carpet: crimson weave with a darker diamond pattern
    yy, xx = np.mgrid[0:N, 0:N]
    weave = ((xx + yy) % 4 < 2) * 0.06 + (((xx - 16) ** 2 + (yy - 16) ** 2) % 97 < 9) * 0.0
    dia = (np.abs((xx % 16) - 8) + np.abs((yy % 16) - 8) == 6) * 1.0
    base = np.array((104, 30, 30), np.float32)
    img = base[None, None] * (1 - weave[..., None]) * (1 - 0.25 * dia[..., None])
    save("carpet", img)
    print("tiles:", sorted(os.listdir(OUT)))


if __name__ == "__main__":
    main()
